const body = $input.first().json.body || $input.first().json;
const message = body.message || '';
const userId = body.userId || body.user_id || 1;

return {
  json: {
    chatInput: message,
    userId: userId
  }
};

const input = $input.first().json;

let message = '';
if (input.output) {
  message = input.output;
} else if (input.text) {
  message = input.text;
} else {
  message = JSON.stringify(input);
}

return {
  json: {
    success: true,
    message: message
  }
};
